#' Compare IV Estimators
#'
#' 
#' @param data .
#' @param outcome .
#' @param endog .
#' @param instruments .
#' @param controls .
#' @param absorb .
#' @param cluster .
#' @param weights .
#' @param vce .
#' @param small .
#' @param alpha .
#' @param level .
#' @param showOls .
#' @param showLiml .
#' @param showFuller .
#' @param showGmm .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cmpPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
ivcmp <- function(
    data,
    outcome,
    endog,
    instruments,
    controls,
    absorb,
    cluster,
    weights,
    vce = "classical",
    small = TRUE,
    alpha = 1,
    level = 95,
    showOls = TRUE,
    showLiml = TRUE,
    showFuller = TRUE,
    showGmm = FALSE,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ivcmp requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(endog)) endog <- jmvcore::resolveQuo(jmvcore::enquo(endog))
    if ( ! missing(instruments)) instruments <- jmvcore::resolveQuo(jmvcore::enquo(instruments))
    if ( ! missing(controls)) controls <- jmvcore::resolveQuo(jmvcore::enquo(controls))
    if ( ! missing(absorb)) absorb <- jmvcore::resolveQuo(jmvcore::enquo(absorb))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(weights)) weights <- jmvcore::resolveQuo(jmvcore::enquo(weights))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(endog), endog, NULL),
            `if`( ! missing(instruments), instruments, NULL),
            `if`( ! missing(controls), controls, NULL),
            `if`( ! missing(absorb), absorb, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(weights), weights, NULL))


    options <- ivcmpOptions$new(
        outcome = outcome,
        endog = endog,
        instruments = instruments,
        controls = controls,
        absorb = absorb,
        cluster = cluster,
        weights = weights,
        vce = vce,
        small = small,
        alpha = alpha,
        level = level,
        showOls = showOls,
        showLiml = showLiml,
        showFuller = showFuller,
        showGmm = showGmm,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ivcmpClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

